-- 05_apf_master_index.sql
-- 278 article-level citations for American Period Furniture, 2001-2023.
--
-- Recovered from `sap_apf_master_index` in the retired Joomla database
-- (R2 joomla4-final-export/db.sql.gz), the only surviving copy. The TOC is
-- freely published as issue promotion (Keith, 2026-08-31), so these citations
-- carry no access restriction. They are CITATIONS ONLY: title, author, volume,
-- year, page. No article text is stored or distributed here.
--
-- card_type is a distinct `apf-article` rather than the generic `article` so a
-- future access decision can address APF alone in one clause, exactly as
-- `apf-issue` does today. Folding them in with the scraped Chipstone/MESDA
-- articles would make that impossible without a source-string hack.
--
-- 2024 has an issue card but no TOC row upstream; its contents need adding by
-- hand. Re-runnable: the DELETE makes this idempotent.

DELETE FROM library_cards WHERE card_type = 'apf-article';

